class OrderedStream {
    vector<string> data;
    int ptr = 1;
public:
    OrderedStream(int n) : data(n + 2) {}

    vector<string> insert(int idKey, string value) {
        data[idKey] = move(value);
        if (idKey != ptr) return {};
        int start = ptr;
        while (!data[ptr].empty()) ++ptr;
        return vector<string>(data.begin() + start, data.begin() + ptr);
    }
};

