class OrderedStream {
    private final String[] data;
    private int ptr = 1;

    public OrderedStream(int n) {
        data = new String[n + 1];
    }

    public List<String> insert(int idKey, String value) {
        data[idKey] = value;
        if (idKey != ptr) return new ArrayList<>();
        List<String> chunk = new ArrayList<>();
        while (ptr < data.length && data[ptr] != null) {
            chunk.add(data[ptr++]);
        }
        return chunk;
    }
}

