class OrderedStream {
    unordered_map<int, string> pending;
    int ptr = 1;
public:
    OrderedStream(int n) {}

    vector<string> insert(int idKey, string value) {
        pending[idKey] = move(value);
        if (idKey != ptr) return {};
        vector<string> chunk;
        while (pending.count(ptr)) {
            chunk.push_back(pending[ptr]);
            pending.erase(ptr++);
        }
        return chunk;
    }
};

