class OrderedStream {
    private final Map<Integer, String> pending = new HashMap<>();
    private int ptr = 1;

    public OrderedStream(int n) {}

    public List<String> insert(int idKey, String value) {
        pending.put(idKey, value);
        if (idKey != ptr) return new ArrayList<>();
        List<String> chunk = new ArrayList<>();
        while (pending.containsKey(ptr)) {
            chunk.add(pending.remove(ptr));
            ptr++;
        }
        return chunk;
    }
}

